const input=document.getElementById("text-input"),output=document.getElementById("text-output");function encodeHtml(){const t=input.value;if(!t)return output.textContent=i18n.t("common.enter_text");const e=document.createElement("div");e.textContent=t,output.textContent=e.innerHTML,output.style.color="var(--text)"}function decodeHtml(){const t=input.value;if(!t)return output.textContent=i18n.t("common.enter_html_entity");const e=document.createElement("div");e.innerHTML=t,output.textContent=e.textContent,output.style.color="var(--text)"}function copyResult(){copyToClipboard(output.textContent).then(()=>showToast(i18n.t("common.copied")))}function downloadResult(){const t=output.textContent;if(!t||t===i18n.t("common.result_placeholder")||t.startsWith("\u274C"))return showToast(i18n.t("common.no_result"));downloadFile(t,"html-result.txt")}function clearAll(){input.value="",output.textContent=i18n.t("common.result_placeholder"),output.style.color="var(--text-muted)"}
